   "id": "z34c91f75",
   "sez": "prima",
   "titolo": "Morte per ricina, nuova perquisizione nella casa della famiglia Di Vita",
   "orig": "Morte avvelenate, nuova perquisizione in casa Di Vita a Pietracatella",
   "lead": "Gli agenti hanno eseguito una nuova perquisizione nell'abitazione della famiglia Di Vita a Pietracatella, nel Campobasso, nell'ambito dell'inchiesta sulla morte per avvelenamento da ricina. Al termine delle verifiche l'immobile verrà dissequestrato, quasi un anno dopo il sequestro iniziale disposto dagli investigatori.",
   "more": [
    "La ricina è una tossina estremamente tossica estratta dai semi di ricino, capace di provocare la morte anche in piccole quantità. I casi di avvelenamento da ricina sono rari e richiedono accertamenti complessi per stabilire modalità e responsabilità, motivo per cui le indagini possono protrarsi per mesi."
   ],
