   "titolo": "Germania, inizia il processo contro i capi del gruppo Reichsbürger",
   "orig": "Germany news: Trial of alleged 'Reichsbürger' group ringleaders begins",
   "lead": "In Germania è iniziato il processo contro quattro presunti capi del movimento di estrema destra \"Regno di Germania\", legato ai cosiddetti Reichsbürger, accusati di appartenenza a un'organizzazione criminale. Il gruppo, che non riconosce la legittimità dello Stato tedesco attuale, è stato dichiarato illegale. Lo riferisce Deutsche Welle.",
   "more": [
    "I Reichsbürger sono un movimento di estrema destra che rifiuta la legittimità della Repubblica Federale di Germania, considerandola illegittima rispetto al Reich tedesco. Negli ultimi anni le autorità tedesche hanno intensificato le indagini su gruppi legati a questa ideologia dopo il sequestro di armi e piani di presunti colpi di Stato."
   ],
