   "sez": "mondo",
   "titolo": "India, nuova richiesta di scarcerazione per gli attivisti Umar Khalid e Sharjeel Imam",
   "orig": "India: Umar Khalid, Sharjeel Imam go back to Supreme Court for bail",
   "lead": "In India gli attivisti Umar Khalid e Sharjeel Imam hanno presentato una nuova richiesta di libertà su cauzione alla Corte suprema, dopo oltre sei anni di detenzione. La Corte ha inoltre chiarito da quando decorrono le 24 ore previste dalla legge per la presentazione di una persona arrestata davanti a un giudice. Lo riferisce Deutsche Welle.",
   "more": [
    "Umar Khalid e Sharjeel Imam sono stati arrestati nell'ambito delle indagini sulle proteste contro la legge sulla cittadinanza del 2019-2020 in India, accusati di reati legati alla sicurezza nazionale. Il loro caso è diventato un simbolo del dibattito sull'uso prolungato della custodia preventiva nei confronti di attivisti e oppositori politici."
   ],
