   "sez": "salute",
   "titolo": "Un medico britannico positivo a ebola curato in un ospedale di Londra",
   "orig": "UK doctor infected with Ebola being treated at London hospital",
   "lead": "Un medico britannico risultato positivo al virus ebola nella Repubblica Democratica del Congo, dove è in corso un'epidemia, è attualmente in cura in un ospedale di Londra. Il governo britannico afferma che il rischio per la popolazione resta basso. Lo riferisce BBC News.",
   "more": [
    "L'ebola è una malattia virale grave, spesso letale, che si trasmette tramite contatto con fluidi corporei di persone infette. La Repubblica Democratica del Congo ha già affrontato numerose epidemie negli ultimi decenni, e casi importati in altri Paesi vengono gestiti con protocolli di isolamento rigorosi per evitare la diffusione del contagio."
   ],
