   "id": "zc0f03ed5",
   "sez": "economia",
   "titolo": "Dopo le elezioni di metà mandato, i repubblicani prendono le distanze dai dazi di Trump",
   "orig": "Republicans ran away from Trump's Canadian tariffs, but not far enough",
   "lead": "Dopo le elezioni di metà mandato negli Stati Uniti, diversi deputati repubblicani hanno cercato di prendere le distanze dalla guerra commerciale sui dazi voluta da Donald Trump, in alcuni casi chiedendo la revoca di specifiche tariffe contro il Canada, ma il partito ha comunque perso diverse corse elettorali. I democratici, tradizionalmente più favorevoli al protezionismo, sembrano ora orientarsi verso posizioni più aperte al libero scambio, aprendo a un possibile accordo bipartisan sul tema dei dazi.",
   "more": [
    "I dazi imposti dall'amministrazione Trump al Canada e ad altri partner commerciali hanno acceso un dibattito politico negli Stati Uniti sui costi economici del protezionismo, con alcuni settori industriali che ne hanno sofferto le conseguenze sui prezzi e sulle esportazioni, influenzando anche gli equilibri elettorali."
   ],
