   "titolo": "Il Museo nazionale estone apre una mostra sull'argenteria tra le due guerre",
   "orig": "Gallery: Estonian National Museum puts its silver collection on display",
   "lead": "Il Museo nazionale estone di Tartu ha inaugurato venerdì la mostra \"Estonian Silver Between the Wars: Well-Known and Lesser-Known Silversmiths, 1918–1944\", dedicata alla collezione di argenteria del museo e agli artigiani attivi nel periodo tra le due guerre mondiali. Lo riferisce ERR News.",
   "more": [
    "Il periodo tra le due guerre mondiali fu per l'Estonia, allora indipendente, un'epoca di sviluppo artistico e artigianale, interrotta poi dall'occupazione sovietica. Le opere di argenteria di quel periodo rappresentano una testimonianza della cultura materiale e artistica del Paese prima dei decenni di dominio sovietico."
   ],
