   "id": "zda110de0",
   "sez": "ingegneria",
   "titolo": "Un nuovo ponte tra Corea del Nord e Russia rischia di restare inutilizzato",
   "orig": "Why a road link to Russia is North Korea’s newest ‘bridge to nowhere’",
   "lead": "Un nuovo ponte stradale che collega la Corea del Nord alla Russia rischia di diventare il nuovo \"ponte verso il nulla\", espressione usata per oltre un decennio per descrivere il New Yalu River Bridge tra Cina e Corea del Nord, rimasto chiuso e inutilizzato fino alla sua recente inaugurazione, avvenuta con grande ritardo il mese scorso. Lo riferisce NK News.",
   "more": [
    "La Corea del Nord ha costruito negli anni diverse infrastrutture di collegamento con i Paesi vicini, Cina e Russia, spesso rimaste inutilizzate per anni a causa di ritardi burocratici, sanzioni internazionali o mancanza di accordi bilaterali completati, nonostante gli investimenti sostenuti per la loro realizzazione."
   ],
