   "id": "z7c291b12",
   "sez": "prima",
   "titolo": "Nuovo allarme bomba su volo da Roma a Lisbona",
   "orig": "Nuovo allarme bomba, su un volo da Roma a Lisbona",
   "lead": "Un nuovo allarme bomba ha riguardato un volo partito da Roma e diretto a Lisbona, dove l'aereo è stato controllato dopo l'atterraggio. L'allerta è arrivata alla Polizia di Stato tramite la telefonata di un agente delle forze dell'ordine, mentre un secondo allarme, segnalato da una chiamata anonima, ha riguardato un volo decollato da Praga. L'episodio segue l'ondata di allarmi avvenuta il giorno precedente, che aveva coinvolto anche un volo Aer Lingus con passeggeri rientrati a Roma. Il Messaggero ipotizza un'azione coordinata, forse legata a un Paese ostile, per creare panico e disturbo nel settore dei servizi, collegata anche a una recente ondata di attacchi informatici.",
   "more": [
    "Gli allarmi bomba su aerei, spesso rivelatisi infondati, creano forti disagi al traffico aereo e mobilitano forze di polizia e servizi di sicurezza. Quando si susseguono in modo coordinato su più voli e Paesi, si valuta anche l'ipotesi di campagne di disturbo deliberate, eventualmente legate ad attacchi informatici contro i sistemi dei trasporti."
   ],
