   "id": "z90827682",
   "sez": "viaggi",
   "titolo": "Il turismo di lusso negli hotel italiani vale 10,4 miliardi di euro",
   "orig": "Turismo di lusso negli alberghi vale 10,4 miliardi, dal 2008 presenze a +111%",
   "lead": "Il turismo di lusso negli hotel italiani vale 10,4 miliardi di euro, con le presenze cresciute del 111% dal 2008, secondo un'analisi dell'istituto Demoskopika. Il segmento resta però fortemente concentrato in poche destinazioni: appena 17 province concentrano il 79% del fenomeno. Lo riferisce ANSA.",
   "more": [
    "Il turismo di lusso rappresenta una quota crescente del settore alberghiero italiano, ma tende a concentrarsi in poche località già affermate a livello internazionale, come grandi città d'arte e destinazioni costiere o montane di pregio, lasciando ampie zone del Paese escluse da questa crescita."
   ],
