   "id": "zb89cbe4d",
   "sez": "cultura",
   "titolo": "Anthony Ippolito dà dolcezza da ko alla storia del trionfo di Stallone a Hollywood",
   "orig": "I Play Rocky review – Anthony Ippolito adds knockout sweetness to the story of Stallone’s Hollywood triumph",
   "lead": "Il Guardian recensisce «I Play Rocky», spettacolo teatrale che racconta la genesi del film «Rocky» di Sylvester Stallone, premiato con l'Oscar nel 1976. La critica evidenzia come l'opera riesca a restituire l'umorismo, la passione e la determinazione che portarono l'attore da ruoli minori alla gloria hollywoodiana. Secondo la recensione, il racconto della creazione del film risulta persino più mitico della pellicola originale, pur senza raggiungerne la profondità.",
   "more": [
    "«Rocky», uscito nel 1976, raccontava l'ascesa di un pugile outsider e divenne uno dei film più celebri della storia del cinema, lanciando la carriera di Sylvester Stallone e vincendo l'Oscar come miglior film. La sua storia di produzione, segnata da un budget limitato e dalla determinazione dell'attore-sceneggiatore, è diventata essa stessa oggetto di narrazioni e opere derivate."
   ],
