   "id": "z8a9b8cdf",
   "sez": "prima",
   "titolo": "Disposta la vigilanza per la gip del caso Siher dopo insulti e minacce",
   "orig": "Dopo insulti e minacce disposta la vigilanza per la gip del caso Siher",
   "lead": "La prefettura di Milano ha disposto un servizio di vigilanza per la giudice che ha deciso la scarcerazione di Youssef Siher, amministratore dei canali social del Movimento 17 ottobre, fermato nell'ambito delle indagini sulle proteste del 17 e 18 ottobre a Milano. La misura è stata richiesta dal presidente del tribunale dopo che la magistrata è stata oggetto di insulti e minacce. La Procura di Milano ha inoltre deciso di non presentare ricorso contro la decisione di scarcerazione.",
   "more": [
    "Il Movimento 17 ottobre è nato in Italia in seguito a mobilitazioni legate a proteste sociali, diventando oggetto di indagini da parte delle procure. Le decisioni dei giudici su misure cautelari nei confronti di attivisti sollevano spesso tensioni pubbliche, con reazioni sui social media che in alcuni casi si sono tradotte in minacce ai magistrati, inducendo le autorità a rafforzare le misure di protezione."
   ],
