   "id": "z97b7a3c2",
   "sez": "dibattito",
   "titolo": "Formazione obbligatoria dei docenti nel giorno libero: quando è dovuta e se le ore si recuperano",
   "orig": "Formazione docenti nel giorno libero, quando è obbligatoria e se le ore possono essere recuperate. Pillole di Question Time",
   "lead": "Nel Question Time di Orizzonte Scuola, condotto da Francesco Bunetto con l'esperto di normativa scolastica Giuseppe Semeraro, si è discusso del caso dei corsi di formazione obbligatoria programmati nel giorno libero dei docenti. Il tema riguarda se la scuola possa imporre ai docenti di partecipare a corsi di formazione nel giorno di riposo settimanale e, in caso affermativo, se le ore impiegate debbano essere recuperate o retribuite. Secondo l'esperto interpellato, la normativa scolastica fornisce indicazioni specifiche su questi casi, chiarite nella trasmissione.",
   "more": [
    "In Italia la formazione continua dei docenti è prevista come obbligo contrattuale, ma le modalità di organizzazione, in particolare quando cadono nei giorni di riposo stabiliti dall'orario di servizio, sono spesso oggetto di dubbi interpretativi tra insegnanti e dirigenti scolastici, regolati da contratti collettivi e circolari ministeriali."
   ],
