   "id": "z2080e834",
   "sez": "salute",
   "titolo": "Uno studio sulle statine mette in discussione i criteri per decidere chi deve assumerle",
   "orig": "Major trial challenges how doctors decide who really needs statins",
   "lead": "Uno studio condotto su quasi 5.800 adulti ha confrontato due metodi per decidere a chi prescrivere le statine contro il rischio cardiovascolare: la valutazione tramite scansioni cardiache che misurano il calcio nelle arterie e i tradizionali questionari di valutazione del rischio. I due approcci hanno portato allo stesso tasso osservato di eventi cardiovascolari maggiori, ma il metodo basato sulle scansioni ha raccomandato le statine a un numero molto inferiore di pazienti. Chi riceveva la prescrizione sulla base della scansione seguiva la terapia con maggiore costanza. Lo riferisce ScienceDaily.",
   "more": [
    "Le statine sono farmaci usati per abbassare il colesterolo e prevenire infarti e ictus. La decisione su chi debba assumerle si basa solitamente su calcolatori di rischio che considerano età, pressione, colesterolo e altri fattori; le scansioni per il calcio coronarico offrono una misura più diretta dell'accumulo di placche nelle arterie."
   ],
