   "id": "zf20915f5",
   "sez": "economia",
   "titolo": "DraftKings riduce le previsioni di utile puntando sui mercati predittivi",
   "orig": "DraftKings slashes earnings guidance as it bets on new prediction market business",
   "lead": "La società di scommesse sportive DraftKings ha tagliato le previsioni sugli utili annunciando forti investimenti in un nuovo settore di business legato ai mercati predittivi, dove cerca di recuperare terreno rispetto a piattaforme come Kalshi e Polymarket. Secondo il Financial Times, l'azienda statunitense sta spendendo risorse significative per entrare in questo segmento emergente, che permette di scommettere sull'esito di eventi reali al di fuori dello sport tradizionale. La revisione al ribasso delle stime riflette i costi legati a questa strategia di espansione.",
   "more": [
    "I mercati predittivi sono piattaforme dove gli utenti scambiano contratti il cui valore dipende dall'esito di eventi futuri, come elezioni o decisioni economiche: un meccanismo simile alle scommesse ma regolato in modo diverso. Negli Stati Uniti aziende come Kalshi e Polymarket hanno guadagnato popolarità, spingendo i tradizionali operatori di scommesse sportive a entrare in questo settore per non perdere quote di mercato."
   ],
