   "id": "zf36604bf",
   "sez": "cultura",
   "titolo": "Apre a Sydney il nuovo museo Powerhouse Parramatta",
   "orig": "Powerhouse Parramatta opens this weekend – and it’s dazzling inside and out",
   "lead": "Il Powerhouse Parramatta, nuovo museo costato 915 milioni di dollari realizzato dagli studi di architettura Moreau Kusunoki e Genton, apre al pubblico a Sydney questo fine settimana con cinque nuove esposizioni e un festival di 23 giorni. L'edificio, descritto come il più grande progetto culturale australiano dai tempi della Sydney Opera House, presenta una struttura esterna a reticolo bianco composta da 1.300 elementi e circa 30.000 metri quadrati di spazi interni. Il progetto ha avuto una storia controversa prima dell'apertura.",
   "more": [
    "Il Powerhouse Museum è una storica istituzione dedicata a scienza, design e cultura australiana; la nuova sede di Parramatta, nella periferia occidentale di Sydney, fa parte di un piano di decentralizzazione culturale della città, pensato per portare grandi istituzioni anche fuori dal centro."
   ],
