   "id": "zce654801",
   "sez": "cultura",
   "titolo": "Una mostra a Praga racconta la storia della scultura del ponte di Barrandov",
   "orig": "Exhibition explores story of iconic Barrandov Bridge sculpture and plans for its return",
   "lead": "A Praga è in corso una mostra dedicata a «Equilibrium», la scultura che per quasi quarant'anni si è trovata accanto al ponte di Barrandov prima di crollare la scorsa estate. L'esposizione ripercorre la storia dell'opera e presenta i progetti per il suo eventuale ritorno nello stesso luogo. Lo riferisce Radio Prague International.",
   "more": [
    "Il ponte di Barrandov è una delle infrastrutture simbolo di Praga; la scultura «Equilibrium», divenuta un punto di riferimento visivo della città, era nota per la sua posizione in equilibrio precario, caratteristica che ha reso particolarmente sentito il suo crollo tra i cittadini e le autorità culturali locali."
   ],
