     "u": "https://www.orizzontescuola.it/arriva-la-certificazione-informatica-sulluso-dellaia-e-lapprendistato-allestero-lue-presenta-le-competenze-per-rafforzare-i-sistemi-educativi-europei-si-punta-anche-su-competenze-di-base-e/",
