   "id": "z8011bd5d",
   "sez": "economia",
   "titolo": "HKEX registra il primo calo trimestrale di utili in oltre due anni",
   "orig": "HKEX posts first quarterly profit decline in over 2 years as Hong Kong market cools",
   "lead": "Hong Kong Exchanges and Clearing (HKEX), operatore della terza borsa più grande dell'Asia, ha riportato il primo calo degli utili trimestrali su base annua in oltre due anni, a causa di un rallentamento del volume degli scambi di mercato. Il profitto netto per il trimestre conclusosi a settembre è sceso dell'1% su base annua a 4,859 miliardi di dollari di Hong Kong (circa 620 milioni di dollari), mancando le stime degli analisti che prevedevano circa 5 miliardi. I profitti sono inoltre diminuiti del 10% rispetto al trimestre precedente, secondo il deposito in borsa.",
   "more": [
    "HKEX è l'operatore della Borsa di Hong Kong, uno dei principali mercati finanziari asiatici e punto di collegamento per gli investimenti internazionali in Cina. L'andamento dei suoi utili è considerato un indicatore della salute generale del mercato finanziario della città, influenzato da fattori come i flussi di capitale internazionali e l'andamento economico cinese."
   ],
