   "id": "zff614696",
   "sez": "economia",
   "titolo": "Ita Airways, accordo con i sindacati per 180 uscite volontarie",
   "orig": "Ita, accordo su 180 uscite volontarie",
   "lead": "Ita Airways e i sindacati Filt-Cgil, Fit-Cisl, Uiltrasporti, Ugl-Ta, Anpac e Anp hanno firmato un accordo che garantisce un sostegno economico per un massimo di 180 uscite volontarie dei dipendenti, un numero inferiore alle 226 ipotizzate inizialmente nella trattativa. L'intesa definisce le condizioni economiche a sostegno dei lavoratori che decideranno di lasciare volontariamente l'azienda, nell'ambito di una riorganizzazione della compagnia aerea.",
   "more": [
    "Ita Airways è la compagnia aerea nata dalla ristrutturazione della precedente Alitalia, ora controllata dal gruppo Lufthansa dopo un'operazione di acquisizione. Gli accordi sulle uscite volontarie sono strumenti usati dalle aziende per ridurre il personale senza licenziamenti forzati, offrendo incentivi economici ai dipendenti che scelgono di andarsene."
   ],
