   "sez": "economia",
   "titolo": "Il mercato azionario indiano in forte rialzo, Sensex e Nifty ai massimi recenti",
   "orig": "Stock markets on fire; Sensex jumps 1,718 points, Nifty reclaims 25,000",
   "lead": "La borsa indiana ha registrato un forte rialzo: il Sensex ha guadagnato 1.718 punti chiudendo a 81.028,02, mentre il Nifty ha superato i 25.000 punti chiudendo a 25.030,35, in rialzo di 494 punti. Nelle ultime sette sedute consecutive il Sensex è salito di 7.781,99 punti, pari al 10,62%, e il Nifty del 10,27%. Il rialzo arriva nonostante una brusca correzione dei mercati azionari globali legata al calo di entusiasmo per i titoli legati all'intelligenza artificiale.",
   "more": [
    "Sensex e Nifty sono i principali indici della borsa indiana, rispettivamente relativi alla Borsa di Mumbai e al National Stock Exchange. Le loro oscillazioni riflettono l'andamento economico del paese e sono spesso influenzate da fattori globali, tra cui i flussi di capitali internazionali e l'andamento dei mercati tecnologici mondiali."
   ],
