   "id": "ze8e2791e",
   "sez": "ambiente",
   "titolo": "Il 2026 sarà probabilmente il secondo anno più caldo di sempre",
   "orig": "2026 'most likely' to be second-hottest year ever - EU",
   "lead": "Il 2026 è destinato a essere il secondo anno più caldo mai registrato, secondo l'osservatorio climatico dell'Unione Europea Copernicus. Un fenomeno El Niño particolarmente intenso ha amplificato il riscaldamento globale causato dalle attività umane. Le temperature globali supereranno 'quasi certamente' la soglia di 1,5 gradi sopra i livelli preindustriali nel corso dell'anno. L'annuncio è stato diffuso venerdì dall'agenzia con sede a Parigi. Il dato confermerebbe la tendenza all'aumento costante delle temperature medie mondiali registrata negli ultimi anni.",
   "more": [
    "El Niño è un fenomeno climatico naturale che si verifica nell'Oceano Pacifico e influisce sulle temperature globali amplificando il riscaldamento causato dai gas serra. L'accordo di Parigi del 2015 fissa l'obiettivo di contenere l'aumento della temperatura media mondiale entro 1,5 gradi rispetto all'epoca preindustriale."
   ],
