   "id": "z3fa19306",
   "sez": "mondo",
   "titolo": "Stati Uniti minacciano di escludere Ruanda e Sudafrica dall'AGOA",
   "orig": "AGOA : les États-Unis menacent d'exclure le Rwanda et l'Afrique du Sud",
   "lead": "L'amministrazione statunitense di Donald Trump intende escludere Ruanda e Sudafrica dall'Africa Growth and Opportunity Act (AGOA), l'accordo che consente a oltre trenta paesi africani di esportare prodotti negli Stati Uniti senza dazi doganali. Per Kigali la decisione arriva in un momento di forte tensione con Washington legato alla guerra nell'est della Repubblica Democratica del Congo. Non sono ancora stati precisati i tempi né le modalità dell'eventuale esclusione dei due paesi dall'accordo commerciale preferenziale. Lo riferisce France 24.",
   "more": [
    "L'AGOA, in vigore dal 2000, garantisce a decine di paesi africani un accesso privilegiato al mercato statunitense tramite l'esenzione dai dazi doganali su migliaia di prodotti. L'accordo viene periodicamente rinnovato dal Congresso americano e la sua applicazione tiene conto anche di considerazioni politiche legate ai rapporti con i singoli paesi beneficiari."
   ],
