   "titolo": "L'emiro del Qatar parla con Trump sulla mediazione per la guerra in Iran",
   "orig": "Qatar’s emir holds call with Trump as mediators push for deal to end Iran war",
   "lead": "L'emiro del Qatar ha avuto una conversazione telefonica con il presidente statunitense Donald Trump nell'ambito degli sforzi di mediazione per porre fine alla guerra con l'Iran. La chiamata arriva pochi giorni dopo che gli elettori americani hanno punito Trump alle elezioni di metà mandato per la guerra in Iran e per i prezzi elevati dei carburanti. Secondo un funzionario iraniano citato da Reuters, Teheran avrebbe inviato una proposta nucleare a Washington tramite il Qatar. I due leader hanno discusso degli sforzi diplomatici guidati da Doha per allentare le tensioni nella regione.",
   "more": [
    "Il Qatar svolge da anni un ruolo di mediatore tra Stati Uniti e Iran, paesi senza relazioni diplomatiche dal 1980. Doha ospita basi militari americane ed è stata coinvolta in passato nei negoziati sul programma nucleare iraniano, oggetto di sanzioni internazionali."
   ],
