   "sez": "economia",
   "titolo": "Le importazioni di Cuba dagli Stati Uniti superano il miliardo di dollari",
   "orig": "Las compras de Cuba a EE UU ya superan los 1.000 millones de dólares este año",
   "lead": "Le importazioni di Cuba dagli Stati Uniti hanno superato i 1.000 milioni di dollari nel corso di quest'anno, con un aumento del 91% rispetto ai primi nove mesi del 2025. I combustibili rappresentano il 30% del totale degli acquisti cubani dagli Stati Uniti. Il dato segna una crescita significativa degli scambi commerciali tra i due paesi, nonostante l'embargo statunitense in vigore da decenni contro l'isola caraibica. Lo riferisce 14ymedio.",
   "more": [
    "Gli Stati Uniti mantengono un embargo commerciale su Cuba dal 1962, ma da tempo consentono eccezioni per la vendita di prodotti agricoli e alimentari in cambio di pagamento in contanti, canale attraverso cui transita gran parte del commercio bilaterale ancora oggi permesso tra i due paesi."
   ],
