   "sez": "mondo",
   "titolo": "Si intensificano gli scontri tra esercito congolese e ribelli FRN nel Nord Kivu",
   "orig": "Les combats s’intensifient entre les FARDC et le FRN sur l’axe Kashebere-Kibati au Nord-Kivu",
   "lead": "Gli scontri tra le Forze armate della Repubblica Democratica del Congo (FARDC) e i ribelli del Fronte per la rifondazione della nazione (FRN) si sono intensificati nei giorni scorsi lungo l'asse Kashebere-Kibati, nel Nord Kivu. La situazione di sicurezza resta tesa venerdì a Kibati, nel territorio di Walikale, secondo fonti locali citate da Radio Okapi. I combattimenti proseguono da almeno due giorni consecutivi nella zona. Non sono stati forniti dettagli su vittime o sfollati legati agli scontri recenti.",
   "more": [
    "Il Nord Kivu, nell'est della Repubblica Democratica del Congo, è teatro da decenni di conflitti armati legati al controllo di risorse minerarie e a tensioni etniche regionali, che coinvolgono numerosi gruppi armati oltre all'esercito governativo, in un contesto di instabilità cronica."
   ],
