   "titolo": "La Turchia prima destinazione dei rimpatri forzati dalla Germania",
   "orig": "Turkey tops Germany’s deportation destinations with over 2,000 returns in first 9 months of 2026",
   "lead": "La Turchia è stata la principale destinazione dei rimpatri forzati dalla Germania nei primi nove mesi del 2026, con 2.025 persone deportate verso il paese. Il dato emerge da statistiche del Ministero dell'Interno tedesco riprese dal servizio turco di Deutsche Welle. In totale, nello stesso periodo, dalla Germania sono state deportate 14.324 persone, nonostante un calo generale delle espulsioni nel paese. Lo riferisce Turkish Minute.",
   "more": [
    "Negli ultimi anni la Germania ha intensificato le politiche di rimpatrio verso i paesi di origine dei migranti irregolari o con richieste d'asilo respinte, in un contesto di crescente pressione politica interna sui temi dell'immigrazione, che ha coinvolto anche accordi bilaterali con diversi paesi."
   ],
